# AI Office v2.5 Part G Response Quality Control Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.5-part-g-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @("config\intelligence","scripts\intelligence","docs")) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)
    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination
    if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath
        if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }
    [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\response-quality-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeResponseQuality.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\New-AIOfficeQualityPrompt.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Invoke-AIOfficeQualityControlledInference.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Enable-AIOfficeResponseQualityControl.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeResponseQualityControl.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5-Part-G-Response-Quality-Control.md" -Base64Content ""
# Back up the live runtime before patching it.
$LiveRuntime = Join-Path $Repository "scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1"
if (Test-Path -LiteralPath $LiveRuntime) {
  $LiveBackup = Join-Path $BackupDirectory "scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1"
  New-Item -ItemType Directory -Path (Split-Path -Parent $LiveBackup) -Force | Out-Null
  Copy-Item -LiteralPath $LiveRuntime -Destination $LiveBackup -Force
}
& "E:\AI\AI-Office\scripts\intelligence\Enable-AIOfficeResponseQualityControl.ps1"
$Scripts = @(
"E:\AI\AI-Office\scripts\intelligence\Test-AIOfficeResponseQuality.ps1",
"E:\AI\AI-Office\scripts\intelligence\New-AIOfficeQualityPrompt.ps1",
"E:\AI\AI-Office\scripts\intelligence\Invoke-AIOfficeQualityControlledInference.ps1",
"E:\AI\AI-Office\scripts\intelligence\Enable-AIOfficeResponseQualityControl.ps1",
"E:\AI\AI-Office\scripts\intelligence\Test-AIOfficeResponseQualityControl.ps1",
"E:\AI\AI-Office\scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1")
foreach ($Script in $Scripts) {
  $Tokens=$null; $ParseErrors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$ParseErrors)|Out-Null
  if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script + ": " + (($ParseErrors|ForEach-Object{$_.Message}) -join "; ")) }
}
Write-Host ""
Write-Host "AI Office v2.5 Part G Response Quality Control installed successfully." -ForegroundColor Green
Write-Host "Live responses now pass through quality instructions and validation." -ForegroundColor Cyan
Write-Host "Existing v2.4 fallback remains intact." -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan